(647, 2, '2016-12-14 23:00:11', '2016-12-14 23:00:11', '@media (max-width: 990px) {\n	.width-50 {\n		width: 50%;\n		transform: translateX(-15%);\n	}\n}\n\nnav#site-navigation .contact-btn {\n    display: none;\n}\n\n#site-header, .has-transparent-header .is-sticky #site-header, .has-vh-transparent .is-sticky #site-header.vertical-header, #searchform-header-replace {\n    background-color: #285430 !important;\n}\n\ndiv#footer-widgets {\n    background-color: #285430 !important;\n}\n\n#footer-widgets li, #footer-widgets #wp-calendar caption, #footer-widgets #wp-calendar th, #footer-widgets #wp-calendar tbody, #footer-widgets .contact-info-widget i, #footer-widgets .oceanwp-newsletter-form-wrap input[type=\"email\"], #footer-widgets .posts-thumbnails-widget li, #footer-widgets .social-widget li a {\n    border-color: #E5D9B6 !important;\n    color: #E5D9B6 !important;\n}\n\nh3.widget-title {\n    border-color: #E5D9B6 !important;\n}\n\nheader.page-header {\n    background: #5F8D4E !important;\n}\n\n#site-navigation-wrap .dropdown-menu >.current-menu-item >a, #site-navigation-wrap .dropdown-menu >.current-menu-ancestor >a, #site-navigation-wrap .dropdown-menu >.current-menu-item >a:hover, #site-navigation-wrap .dropdown-menu >.current-menu-ancestor >a:hover, #site-navigation-wrap .dropdown-menu >li >a:hover, .oceanwp-mobile-menu-icon a:hover, #searchform-header-replace-close:hover {\n    color: #A4BE7B !important;\n}\n\n#footer-widgets li, #footer-widgets #wp-calendar caption, #footer-widgets #wp-calendar th, #footer-widgets #wp-calendar tbody, #footer-widgets .contact-info-widget i, #footer-widgets .oceanwp-newsletter-form-wrap input[type=\"email\"], #footer-widgets .posts-thumbnails-widget li, #footer-widgets .social-widget li a {\n    color: white !important;\n    border-color: white !important;\n}\n\ndiv#footer-bottom {\n    display: none !important;\n}', 'oceanwp-child-theme-master', '', 'publish', 'closed', 'closed', '', 'oceanwp-child-theme-master-2', '', '', '20